/// <summary>
///  PaffH 21.10.25
/// </summary>
/// <param name = "_entityCtx"></param>
/// <param name = "_dataSourceCtx"></param>
/// <returns></returns>
public boolean insertEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret;

    ret = super(_entityCtx, _dataSourceCtx);

    this.writeDatasourcesExclusiveRoot(_entityCtx, _dataSourceCtx);

    return ret;
}

/// <summary>
///  PaffH 21.10.25
/// </summary>
/// <param name = "_entityCtx"></param>
/// <param name = "_dataSourceCtx"></param>
/// <returns></returns>
public boolean updateEntityDataSource(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    boolean ret;

    ret = super(_entityCtx, _dataSourceCtx);

    this.writeDatasourcesExclusiveRoot(_entityCtx, _dataSourceCtx);

    return ret;
}

/// <summary>
/// PaffH 21.10.25
/// last modified: PaffH 08.12.25
/// save changes to NDXBVEMailRequestHeaderAIDecisionBasis and NDXBVEMailRequestHeaderAIInfo
/// </summary>
/// <param name = "_entityCtx">DataEntityRuntimeContext</param>
/// <param name = "_dataSourceCtx">DataEntityDataSourceRuntimeContext</param>
protected void writeDatasourcesExclusiveRoot(DataEntityRuntimeContext _entityCtx, DataEntityDataSourceRuntimeContext _dataSourceCtx)
{
    NDXBVEMailRequestHeader nDXBVEMailRequestHeader = _dataSourceCtx.getBuffer();
    if (NDXBVEMailRequestHeader::exists(nDXBVEMailRequestHeader.RecId))
    {
        DataEntityDataSourceRuntimeContext deDsContext = _entityCtx.getRuntimeContextByName(dataEntityDataSourceStr(NDXBVEMailRequestHeaderEntity, NDXBVEMailRequestHeaderAIDecisionBasis));
        if (deDsContext)
        {
            NDXBVEMailRequestHeaderAIDecisionBasis buffer = deDsContext.getBuffer();
            NDXBVEMailRequestHeaderAIDecisionBasis nDXBVEMailRequestHeaderAIDecisionBasis = NDXBVEMailRequestHeaderAIDecisionBasis::findOrCreate(nDXBVEMailRequestHeader.RecId);
            nDXBVEMailRequestHeaderAIDecisionBasis.initFromNDXBVEMailRequestHeaderAIDecisionBasis(buffer);
            if (nDXBVEMailRequestHeaderAIDecisionBasis.validateWrite())
            {
                ttsbegin;
                nDXBVEMailRequestHeaderAIDecisionBasis.write();
                ttscommit;
            }
        }
        deDsContext = _entityCtx.getRuntimeContextByName(dataEntityDataSourceStr(NDXBVEMailRequestHeaderEntity, NDXBVEMailRequestHeaderAIInfo));
        if (deDsContext)
        {
            NDXBVEMailRequestHeaderAIInfo buffer = deDsContext.getBuffer();
            NDXBVEMailRequestHeaderAIInfo nDXBVEMailRequestHeaderAIInfo = NDXBVEMailRequestHeaderAIInfo::findOrCreate(nDXBVEMailRequestHeader.RecId);
            nDXBVEMailRequestHeaderAIInfo.initFromNDXBVEMailRequestHeaderAIInfo(buffer);
            if (nDXBVEMailRequestHeaderAIInfo.validateWrite())
            {
                ttsbegin;
                nDXBVEMailRequestHeaderAIInfo.write();
                ttscommit;
            }
        }
        deDsContext = _entityCtx.getRuntimeContextByName(dataEntityDataSourceStr(NDXBVEMailRequestHeaderEntity, NDXBVEMailRequestState));
        if (deDsContext)
        {
            NDXBVEMailRequestState buffer = deDsContext.getBuffer();
            NDXBVEMailRequestState nDXBVEMailRequestState = NDXBVEMailRequestState::findOrCreate(nDXBVEMailRequestHeader);
            nDXBVEMailRequestState.initFromNDXBVEMailRequestState(buffer);
            if (nDXBVEMailRequestState.validateWrite())
            {
                ttsbegin;
                nDXBVEMailRequestState.write();
                ttscommit;
            }
        }
    }
}
